'use strict';
function adminSecuritySettings(){return `<section class="panel integration-card"><h2>Super админы нууц үг солих</h2><p>Шинэ нууц үгээ хадгалахад бусад төхөөрөмжийн админ нэвтрэлт хаагдана.</p><form id="admin-password-form"><div class="form-grid"><label class="full">Одоогийн нууц үг<input name="current_password" type="password" autocomplete="current-password" required maxlength="1000"></label><label>Шинэ нууц үг<input name="new_password" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label><label>Шинэ нууц үгээ давтах<input name="password_confirm" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label></div><p class="muted">12-оос доошгүй тэмдэгттэй шинэ нууц үг сонгоно уу.</p><p class="error" role="alert"></p><button class="primary" type="submit">Нууц үг солих</button></form></section>`;}
function deleteProduct(id){const p=data.products.find(x=>x.id===id);if(!p)return;modal('Бараа устгах',`<form id="product-delete-form"><input type="hidden" name="id" value="${esc(p.id)}"><input type="hidden" name="confirm_id" value="${esc(p.id)}"><p><strong>${esc(p.name)}</strong> барааг каталог болон админы жагсаалтаас хасна. Өмнөх захиалгын мэдээлэл хадгалагдана.</p><label class="check"><input type="checkbox" required>Энэ барааг устгахыг баталгаажуулж байна.</label><p class="error" role="alert"></p><div class="form-actions"><button class="quiet" type="button" data-close>Болих</button><button class="primary danger" type="submit">Бараа устгах</button></div></form>`);}
function supplierIntegrationSettings(){
return `<section class="panel integration-card"><h2>Taobao · OT Commerce</h2><p>Каталог Taobao provider ашиглаж байна. Барааны үнэ CNY-ээр ирж, сайтын ханшаар төгрөгт хөрвөнө.</p><p>GOStore захиалгын хүсэлтийг хүлээн авч, админ бараа болон хүргэлтийн үнийг баталгаажуулна. Төлбөр орсон захиалгыг доорх «Taobao худалдан авалт» хэсгээр Эрээн агуулах руу API-аар захиална.</p><p class="muted">API түлхүүр серверт хадгалагдана. Каталогийн идэвх, ханш, өдрийн дуудлагын хязгаарыг доорх тохиргооноос удирдана.</p></section>`;
}
function warehouseFields(p={}){return `<div class="form-grid"><label>Агуулахын нэр<input name="name" maxlength="150" value="${esc(p.name||'')}" required></label><label>Хот / дүүрэг<input name="city" maxlength="100" value="${esc(p.city||'')}" required></label><label class="full">Хаяг<textarea name="address" maxlength="1000" required>${esc(p.address||'')}</textarea></label><label>Үндсэн утас<input name="phone" type="tel" maxlength="80" value="${esc(p.phone||'')}" required></label><label>Нэмэлт утас<input name="contact_phone" type="tel" maxlength="80" value="${esc(p.contact_phone||'')}"></label><label class="full">Ажиллах цаг<input name="hours" maxlength="300" value="${esc(p.hours||'')}" placeholder="Даваа–Бямба 09:00–18:00"></label></div>`;}
const warehouseRoleLabel=role=>role==='erenhot'?'Хүлээн авах · багцлан илгээх':'Багц хүлээн авах · хэрэглэгчид олгох';
function warehouseSettings(){const all=Object.values(data.warehouse_profiles),rows=all.filter(w=>(w.name+' '+w.city+' '+w.address).toLowerCase().includes(query.toLowerCase()));return `<div class="page-intro"><div><p class="eyebrow">АГУУЛАХЫН СҮЛЖЭЭ</p><h2>Салбар бүр, нэг удирдлага</h2><p>Тусдаа менежер, хаяг болон захиалгын хуваарилалт.</p></div><button class="primary" data-new-warehouse>＋ Агуулах нэмэх</button></div><div class="warehouse-summary"><span><strong>${all.length}</strong> агуулах</span><span><strong>${all.filter(w=>w.active).length}</strong> идэвхтэй</span><span><strong>${Object.values(data.warehouse_accounts).filter(a=>a.enabled&&a.configured&&data.warehouse_profiles[a.location]?.active).length}</strong> менежерийн эрх</span></div><div class="toolbar"><input id="list-search" aria-label="Агуулах хайх" placeholder="Агуулахын нэр, хот, хаягаар хайх…" value="${esc(query)}"><button class="quiet" data-refresh>↻ Шинэчлэх</button></div><p class="muted">Захиалгын дэлгэрэнгүйгээс эхлэх болон хүлээн авах агуулахыг онооно. Нэг багцад ижил чиглэлтэй захиалгууд орно.</p><div class="warehouse-grid">${rows.map(p=>{const a=data.warehouse_accounts[p.location],assigned=data.orders.filter(o=>(o.warehouse_locations?.[p.role]||p.role)===p.location&&(o.route||[]).includes('Эрээн')&&!['completed','cancelled'].includes(o.status)).length;return `<article class="panel warehouse-card" data-warehouse-card="${p.location}"><div class="warehouse-card-heading"><span class="warehouse-mark" aria-hidden="true">▣</span><div><small>${esc(p.city)}</small><h2>${esc(p.name)}</h2></div><span class="tag ${p.active?'green':'gray'}">${p.active?'Идэвхтэй':'Түр хаасан'}</span></div><p class="warehouse-role">${warehouseRoleLabel(p.role)} · ${p.role==='erenhot'?'中文':'Монгол'}</p><p class="warehouse-address">${esc(p.address||'Хаяг оруулаагүй')}</p><p class="muted">${esc(p.phone||'Утас оруулаагүй')} · ${esc(p.hours||'Цаг оруулаагүй')}</p><div class="warehouse-card-metrics"><span><strong>${assigned}</strong> нээлттэй захиалга<small>Сүүлийн 1000 хүсэлтээс</small></span><span class="tag ${p.active&&a.enabled&&a.configured?'green':'yellow'}">${p.active&&a.enabled&&a.configured?'Менежер идэвхтэй':'Менежер тохируулах'}</span></div><a class="quiet warehouse-open" href="../warehouse/${encodeURIComponent(p.location)}/" target="_blank" rel="noopener">Менежерийн панел нээх ↗</a><details class="warehouse-edit"><summary>Мэдээлэл засах</summary><form data-warehouse-profile="${p.location}">${warehouseFields(p)}${p.location.startsWith('wh-')?`<label class="check"><input type="checkbox" name="active" ${p.active?'checked':''}>Агуулах идэвхтэй</label><p class="muted">Дуусаагүй захиалгатай агуулахыг түр хаахгүй.</p>`:''}<p class="error" role="alert"></p><button class="primary" type="submit">Мэдээлэл хадгалах</button></form></details><details class="warehouse-edit"><summary>Менежерийн эрх · ${esc(a.email||'Тохируулаагүй')}</summary><form data-warehouse-account="${p.location}"><label>Менежерийн имэйл<input name="email" type="email" autocomplete="off" maxlength="200" value="${esc(a.email)}" required></label><label>${a.configured?'Шинэ нууц үг':'Анхны нууц үг'}<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="72" ${a.configured?'':'required'}><small>${a.configured?'Хоосон үлдээвэл одоогийн нууц үгийг хадгална.':'12-оос доошгүй тэмдэгт оруулна уу.'}</small></label><label class="check"><input type="checkbox" name="enabled" ${a.enabled?'checked':''}>Менежерийн эрх идэвхтэй</label><p class="muted">Хадгалахад энэ менежерийн нэвтэрсэн төхөөрөмжүүдээс гаргана.</p><p class="error" role="alert"></p><button class="primary" type="submit">Эрх хадгалах</button></form></details></article>`;}).join('')}</div>${rows.length?'':'<div class="empty">Тохирох агуулах алга. Нэр эсвэл хотын хайлтаа өөрчилнө үү.</div>'}`;}
function newWarehouse(){modal('Агуулах нэмэх',`<form id="warehouse-create-form"><p class="muted">Агуулах болон менежерийн эрхийг хамт үүсгэнэ.</p><label>Агуулахын үүрэг<select name="role"><option value="ulaanbaatar">Багц хүлээн авах, ангилах, хэрэглэгчид олгох · Монгол</option><option value="erenhot">Бараа хүлээн авах, багцлах, илгээх · 中文</option></select><small>Үүргийг үүсгэсний дараа солихгүй.</small></label>${warehouseFields()}<h3>Менежерийн нэвтрэх эрх</h3><div class="form-grid"><label>Имэйл<input name="email" type="email" maxlength="200" autocomplete="off" required></label><label>Анхны нууц үг<input name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required></label></div><p class="error" role="alert"></p><div class="form-actions"><button class="quiet" type="button" data-close>Болих</button><button class="primary" type="submit">Агуулах үүсгэх</button></div></form>`);}
function warehouseAssignment(o){if(!(o.route||[]).includes('Эрээн'))return '';const locations=o.warehouse_locations||{erenhot:'erenhot',ulaanbaatar:'ulaanbaatar'},locked=!!o.batch_id||!['new','reviewing','quoted','confirmed','shipping','erenhot'].includes(o.status);return `<section class="order-warehouse-assignment"><h3>Захиалгын агуулах</h3>${locked?`<p>${esc(data.warehouse_profiles[locations.erenhot]?.name)} → ${esc(data.warehouse_profiles[locations.ulaanbaatar]?.name)}</p><p class="muted">Багцалсан эсвэл хүлээн авсан захиалгын чиглэл түгжигдсэн.</p>`:`<form id="warehouse-assign-form"><input type="hidden" name="id" value="${esc(o.id)}"><input type="hidden" name="expected_status" value="${o.status}"><div class="form-grid">${['erenhot','ulaanbaatar'].map(role=>`<label>${role==='erenhot'?'Эхлэх агуулах':'Хүлээн авах агуулах'}<input type="hidden" name="expected_${role}" value="${esc(locations[role])}"><select name="${role}">${Object.values(data.warehouse_profiles).filter(w=>w.role===role&&(w.active||w.location===locations[role])).map(w=>`<option value="${w.location}" ${w.location===locations[role]?'selected':''}>${esc(w.name)}${w.active?'':' · Түр хаасан'}</option>`).join('')}</select></label>`).join('')}</div><p class="muted">Багцлахаас өмнө чиглэлээ сонгоно. Илгээсэн барааны эхлэх агуулахыг солихгүй.</p><p class="error" role="alert"></p><button type="submit" class="quiet">Агуулах оноох</button></form>`}</section>`;}
function warehouseLabel(o){if(!o.warehouse)return '';return `<section class="panel integration-card"><h3>Нийлүүлэгчид өгөх хүргэлтийн мэдээлэл</h3><p>Хятадад худалдан авахдаа доорх хүлээн авагч, утас, хаягийг ашиглана. Овог нэр болон захиалгын кодыг илгээмжийн шошгод заавал бичүүлнэ.</p><label>${esc(data.warehouse_profiles[o.warehouse_locations?.erenhot||'erenhot']?.name||'Агуулах')} · захиалга ${esc(o.id)}<textarea id="warehouse-label" rows="6" readonly style="width:100%;white-space:pre-wrap">${esc(o.warehouse.label)}</textarea></label><button class="quiet" type="button" data-copy-warehouse>Хаяг, овог нэр, код хуулах</button></section>`;}
const shippingNumbers=['cny_rate','service_percent','service_fee_mnt','domestic_default_cny','payment_window_hours','home_min_price_mnt'];
function shippingSettings(){const s=data.shipping;const labels={cny_rate:'1 юань (₮)',service_percent:'Барааны үнээс үйлчилгээний шимтгэл (%)',service_fee_mnt:'Захиалга бүрийн тогтмол хураамж (₮)',domestic_default_cny:'Хятад доторх хүргэлт · нэг дэлгүүр (¥)',payment_window_hours:'Төлбөр хүлээх хугацаа (цаг)',home_min_price_mnt:'Нүүр хуудасны доод үнэ (₮)',api_daily_limit:'Taobao API: өдрийн дуудлагын дээд тоо'};return `<section class="panel integration-card"><h2>Ханш ба карго</h2><p>Нийлүүлэгч → Эрээн агуулах → Замын-Үүд → Улаанбаатар. ${esc(GOStoreCargo.tariff(s))} Шинэ ханш өмнөх хадгалсан үнийн санал, QPay нэхэмжлэлийг өөрчлөхгүй.</p><form id="shipping-form"><div class="form-grid">${Object.entries(labels).map(([k,v])=>`<label>${v}<input name="${k}" type="number" step="${['api_daily_limit','payment_window_hours','home_min_price_mnt'].includes(k)?'1':'0.001'}" min="${['api_daily_limit','payment_window_hours'].includes(k)?'1':['cny_rate','weight_step_kg','volume_threshold'].includes(k)?'0.001':'0'}" value="${s[k]}" required></label>`).join('')}</div><label class="check"><input type="checkbox" name="supplier_enabled" ${s.supplier_enabled?'checked':''}>Taobao каталог идэвхтэй</label><label>Каталогийн холболт<select name="catalog_provider"><option value="taoworld" selected>TaoWorld · шууд API</option>${s.catalog_provider==='taoworld'?'':'<option value="otcommerce" selected>OT Commerce · хуучин холболт</option>'}</select></label><label>Барааны нэр, үзүүлэлтийн хэл<select name="catalog_language"><option value="mn" ${s.catalog_language!=='en'?'selected':''}>Монгол</option><option value="en" ${s.catalog_language==='en'?'selected':''}>English</option></select></label><label class="check"><input type="checkbox" name="image_search_enabled" ${s.image_search_enabled?'checked':''}>Зургаар хайх (камер) идэвхтэй</label><p class="muted">Шимтгэл одоогоор ${s.service_percent}%. API лимит нь сайтын өдрийн хязгаар; нийлүүлэгчийн үлдэгдэл эрхийг илэрхийлэхгүй. TaoWorld каталог англи орчуулгаар харагдана. Хайлтын боломж нь холбогдсон дансны барааны хүрээ, API эрхээс хамаарна. Жин, хэмжээс тодорхойгүй үед админ үнийн санал гаргана.</p><p id="form-error" class="error" role="alert"></p><button class="primary" type="submit">Тохиргоо хадгалах</button></form></section>`;}
function quoteText(q){const b=q.breakdown;return `Бараа ${money(b.goods_mnt)} + Хятад хүргэлт ${money(b.domestic_mnt)} + үйлчилгээ ${money(b.service_mnt)} + карго ${money(b.cargo_mnt)} = ${money(q.total)}`;}
function quoteCalculator(o){const i=o.quote?.inputs||{goods_cny:o.supplier?.goods_cny||0,domestic_cny:0};return `<details class="panel integration-card" ${o.supplier?'open':''}><summary>Ханш, каргоор үнийн санал тооцох</summary><p>Бүх барааны нийт үнэ, нийт жин болон савласан нийт эзлэхүүнийг оруулна. Тариф автоматаар сонгогдоно.</p><form id="quote-form"><input type="hidden" name="cargo_method" value="auto"><div class="form-grid">${[['goods_cny','Барааны нийт дүн (¥)',0],['domestic_cny','Хятад доторх хүргэлт (¥)',0],['weight_kg','Нийт жин (кг)',0.001],['volume_m3','Нийт эзлэхүүн (м³)',0.000000001]].map(([key,label,min])=>`<label>${label}<input name="${key}" type="number" min="${min}" step="any" value="${esc(i[key]??'')}" required></label>`).join('')}</div><button class="primary" type="submit">Тооцоод нийт саналд оруулах</button><p id="quote-result" role="status">${o.quote?esc(quoteText(o.quote)):''}</p><p class="error" role="alert"></p></form></details>`;}
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US').format(v)+' ₮';
const categories={home:'Гэр ахуй',tech:'Электроник',bags:'Цүнх, үүргэвч',shoes:'Гутал',accessories:'Аксессуар',beauty:'Гоо сайхан',lighting:'Гэрэлтүүлэг'};
const statuses={new:'Шинэ хүсэлт',reviewing:'Шалгаж байна',quoted:'Үнийн саналтай',confirmed:'Баталгаажсан',shipping:'Хүргэлтэд',erenhot:'Эрээн агуулахад ирсэн',erenhot_ready:'Улаанбаатар луу гарахад бэлэн',erenhot_dispatched:'Замын-Үүд рүү явж байна',zamyn_uud:'Замын-Үүдэд',ulaanbaatar:'Улаанбаатарт хүлээн авсан',ulaanbaatar_unsorted:'Багцаар ирсэн · ангилаагүй',ready_pickup:'Агуулахаас авахад бэлэн',ready_delivery:'Хүргэлтэд гаргахад бэлэн',out_for_delivery:'Хүргэлтэд гарсан',completed:'Хүлээлгэн өгсөн',cancelled:'Цуцалсан'};
const titles={reviews:'Үнэлгээ, сэтгэгдэл',messages:'Мэдэгдэл илгээх',overview:'Хянах самбар',products:'Бараа бүтээгдэхүүн',orders:'Захиалгууд',customers:'Хэрэглэгчид',links:'Хятад захиалга',integrations:'API холболтууд',shipping:'Ханш ба карго',warehouse:'Агуулахууд',security:'Нууц үг солих',...(window.ADMIN_EXTRA_TITLES||{})};
let csrf='',data={products:[],orders:[],qpay:{}},page=Object.hasOwn(titles,location.hash.slice(1))?location.hash.slice(1):'overview',query='',statusFilter='all';
async function api(action,body){const r=await fetch('../api/index.php?action='+action,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:body?JSON.stringify(body):undefined,credentials:'same-origin'});let d;try{d=await r.json();}catch{throw Error('PHP серверээр ажиллуулна уу. README дахь зааврыг үзээрэй.');}if(!r.ok){if(r.status===401&&action!=='login'){$('#app').hidden=true;$('#login-screen').hidden=false;}throw Error(d.error||'Холболтын алдаа');}if(d.csrf)csrf=d.csrf;return d;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function tag(status){return `<span class="tag ${['completed','confirmed'].includes(status)?'green':status==='new'?'yellow':status==='cancelled'?'gray':''}">${esc(statuses[status]||status)}</span>`;}
const date=v=>new Date(v).toLocaleDateString('mn-MN');
function orderTable(rows){return rows.length?`<div class="table-wrap orders-table-wrap"><table class="orders-table" aria-label="Захиалгын жагсаалт"><colgroup><col class="order-col-main"><col class="order-col-customer"><col class="order-col-amount"><col class="order-col-status"><col class="order-col-action"></colgroup><thead><tr><th scope="col">Захиалга</th><th scope="col">Хэрэглэгч</th><th scope="col">Нийт санал</th><th scope="col">Төлөв</th><th scope="col"><span class="admin-sr-only">Үйлдэл</span></th></tr></thead><tbody>${rows.map(o=>`<tr><td class="order-main"><div class="order-heading"><strong class="order-code">${esc(o.id)}</strong><time class="order-date" datetime="${esc(o.created)}">${esc(new Date(o.created).toLocaleDateString('sv-SE',{timeZone:'Asia/Ulaanbaatar'}))}</time></div><span class="order-title" title="${esc(o.title)}">${esc(o.title)}</span></td><td class="order-customer" data-label="Хэрэглэгч"><span>${esc(o.customer)}</span><small>${esc(o.phone)}</small></td><td class="order-amount" data-label="Нийт санал"><strong>${o.amount?money(o.amount):'Үнэ хүлээгдэж байна'}</strong><small class="order-payment ${o.paid?'is-paid':''}">${o.paid?'Төлөгдсөн':'Төлбөр хүлээгдэж байна'}${o.demo?' · Жишээ':''}</small></td><td class="order-status" data-label="Төлөв"><button class="order-track-trigger" type="button" data-admin-track="${esc(o.id)}" aria-label="${esc(o.id)} ачааны явц харах">${tag(o.status)}<span aria-hidden="true">↗</span></button></td><td class="order-action"><button class="quiet" data-order="${esc(o.id)}" aria-label="${esc(o.id)} захиалгын дэлгэрэнгүй">Харах →</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>Захиалга хараахан алга</h3>Дэлгүүрээс илгээсэн хүсэлтүүд энд харагдана.</div>`;}
function overview(){const newOrders=data.orders.filter(o=>o.status==='new'),paid=data.orders.filter(o=>o.paid),low=data.products.filter(p=>p.active&&p.type==='local'&&!p.demo&&p.stock<5);return `<div class="welcome"><div><span class="eyebrow">ТАНЫ ӨДӨР ТУТМЫН ТОЙМ</span><h2>Сайн байна уу, GOStore 👋</h2><p>Дэлгүүрийнхээ сонголт, захиалга бүрийг нэг дороос.</p></div><button class="primary yellow" data-page="orders">Захиалгууд харах →</button></div><div class="stats"><div class="stat"><span>Нийт бараа</span><strong>${data.products.length}</strong><small>${data.products.filter(p=>p.active).length} нийтлэгдсэн</small></div><div class="stat"><span>Шинэ хүсэлт</span><strong class="blue">${newOrders.length}</strong><small>Таны хариуг хүлээж байна</small></div><div class="stat"><span>Хятад захиалга</span><strong>${data.orders.filter(o=>['link','supplier','checkout'].includes(o.type)).length}</strong><small>Үнэ, нөхцөл баталгаажуулна</small></div><div class="stat"><span>QPay баталгаажсан</span><strong style="font-size:23px">${money(paid.reduce((s,o)=>s+o.amount,0))}</strong><small>${paid.length} төлбөр · сүүлийн 1000 хүсэлт</small></div></div><div class="admin-shortcuts"><button class="quiet" data-page="orders">▤ Захиалга шалгах</button><button class="quiet" data-page="warehouse">▣ Агуулах удирдах</button><button class="quiet" data-page="shipping">¥ Ханш, карго</button></div><section class="panel"><div class="panel-heading"><div><h3>Сүүлийн хүсэлтүүд</h3><p>Шинээр ирсэн захиалгуудаа шалгаарай</p></div><button class="quiet" data-page="orders">Бүгдийг харах →</button></div>${orderTable(data.orders.slice(0,5))}</section><div class="two-col"><section class="panel"><div class="panel-heading"><h3>Холболтын төлөв</h3><button class="quiet" data-page="integrations">Тохиргоо</button></div><div class="connection"><span class="connection-icon">Q</span><div><h3>QPay төлбөр</h3><p>${data.qpay.enabled?'Merchant тохиргоо оруулсан':'Төлбөр авах горим идэвхгүй'}</p></div><span class="tag ${data.qpay.enabled?'green':'yellow'}">${data.qpay.enabled?esc(data.qpay.environment):'Тохируулаагүй'}</span></div><div class="connection"><span class="connection-icon">↗</span><div><h3>Taobao · Карго API</h3><p>Taobao каталог, хувилбар ба үнэ · каргоны явцыг админ шинэчилнэ</p></div><span class="tag green">Каталог холбогдсон</span></div></section><section class="panel"><div class="panel-heading"><h3>Үлдэгдлийн анхааруулга</h3><span class="tag yellow">${low.length}</span></div>${low.length?low.map(p=>`<div class="connection"><div><h3>${esc(p.name)}</h3><p>${p.stock} ширхэг үлдсэн</p></div><button class="quiet" data-product="${esc(p.id)}">Засах</button></div>`).join(''):'<div class="empty">Бага үлдэгдэлтэй бодит бараа алга.</div>'}</section></div>`;}
function productList(){const rows=data.products.filter(p=>(p.name+' '+p.id).toLowerCase().includes(query.toLowerCase()));return `<div class="toolbar"><input id="list-search" aria-label="Бараа хайх" placeholder="Барааны нэр, кодоор хайх…" value="${esc(query)}"><button class="primary" data-new>＋ Бараа нэмэх</button></div><section class="panel"><div class="panel-heading"><h3>Барааны каталог</h3>${!data.local_products_enabled?'<p>Бэлэн барааны худалдаа түр зогссон. Бүртгэлүүд хадгалагдаж байна.</p>':''}<span class="muted">${rows.length} бараа</span></div><div class="table-wrap"><table><thead><tr><th>Бүтээгдэхүүн</th><th>Үнэ</th><th>Үлдэгдэл</th><th>Харагдац</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="product-cell"><img src="../assets/${esc(p.image)}.jpg" alt=""><div><strong>${esc(p.name)}</strong><small>${esc(categories[p.category])} · ${p.type==='local'?'Бэлэн':'Захиалгаар'}${p.demo?' · Жишээ':''}</small></div></div></td><td>${money(p.price)}</td><td>${p.type==='local'?p.stock+' ш':'Захиалгаар'}</td><td><span class="tag ${p.active?'green':'gray'}">${p.active?'Нийтлэгдсэн':'Нуусан'}</span></td><td><button class="quiet" data-product="${esc(p.id)}">Засах</button> <button class="quiet danger" data-delete-product="${esc(p.id)}">Устгах</button></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty">Тохирох бараа алга.</div>'}</section>`;}
function ordersList(){const rows=data.orders.filter(o=>(page!=='links'||['link','supplier','checkout'].includes(o.type))&&(statusFilter==='all'||o.status===statusFilter)&&(o.id+' '+o.title+' '+o.customer+' '+o.phone).toLowerCase().includes(query.toLowerCase()));return `<div class="toolbar orders-toolbar"><input id="list-search" aria-label="Захиалга хайх" placeholder="Нэр, утас, захиалгын дугаар…" value="${esc(query)}"><select id="status-filter" aria-label="Төлөвөөр шүүх"><option value="all">Бүх төлөв</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${statusFilter===k?'selected':''}>${v}</option>`).join('')}</select><button class="quiet" data-refresh>↻ Шинэчлэх</button></div><section class="panel orders-panel"><div class="panel-heading"><h3>${page==='links'?'Хятад захиалгууд':'Бүх захиалгын хүсэлт'}</h3><span class="muted">${rows.length} хүсэлт</span></div>${orderTable(rows)}</section>`;}
// Taobao buyer account: paid orders are bought from Taobao and shipped to the Erenhot warehouse.
const adminTime=v=>v?new Date(v).toLocaleString('mn-MN'):'—';
function taoworldDirectSettings(){return twSettingsPanel();}
function taobaoBuyerSettings(){const t=data.taobao_buyer||{},r=t.receiver||{};return `<section class="panel integration-card" id="taobao-buyer"><h2>OT Commerce · Taobao худалдан авалт</h2><p>Төлбөр орсон захиалгыг Taobao Global данснаас OT API-аар захиалж, Эрээн агуулах руу илгээнэ.</p><p class="muted">Хүлээн авагч: ${esc(r.name)} · ${esc(r.mobile_phone)}<br>${esc([r.state,r.city,r.district,r.address].join(' '))}</p>${t.connected?`<p>Холбогдсон данс: <strong>${esc(t.account||'Taobao Global')}</strong><br>Токен дуусах: ${adminTime(t.expires_at)} · Шинэчлэх эрх: ${adminTime(t.refresh_expires_at)}</p><label class="check"><input type="checkbox" data-taobao-auto ${t.auto_purchase?'checked':''}>Төлбөр ормогц автоматаар Taobao-д захиалах</label><div class="form-actions"><button class="quiet" data-taobao-connect>OT Commerce-оор дахин холбох</button><button class="quiet danger" data-taobao-disconnect>Салгах</button></div>`:`<p class="muted">Данс холбогдоогүй. Захиалга бүрийг гараар худалдаж авна.</p><button class="primary" data-taobao-connect>OT Commerce-оор данс холбох</button>`}</section>`;}
function purchasePanel(o){if(o.purchase?.provider==='taoworld'||(!o.purchase&&o.type==='checkout'))return twPurchasePanel(o);if(!['checkout','supplier'].includes(o.type))return '';const p=o.purchase||{},labels={creating:'Илгээж байна',created:'Taobao-д захиалсан',failed:'Амжилтгүй',review:'Шалгах шаардлагатай'};return `<section class="panel purchase-panel"><h3>Эрээн рүү Taobao захиалга</h3><p><strong>${esc(labels[p.state]||'Захиалаагүй')}</strong>${p.order_id?' · Дугаар: '+esc(p.order_id):''}${p.provider_order_ids?.length?' · Taobao: '+p.provider_order_ids.map(esc).join(', '):''}${p.auto?' · автомат':''}</p>${p.error?`<p class="error">${esc(p.error)}</p>`:''}${p.tracked_at?`<details><summary>Хүргэлтийн мэдээлэл · ${adminTime(p.tracked_at)}</summary><pre class="purchase-json">${esc(p.tracking)}</pre></details>`:''}${(o.inbound?.numbers||[]).length?`<p>Эрээн рүү tracking: ${o.inbound.numbers.map(n=>`<strong>${esc(n.no)}</strong>${n.company?' ('+esc(n.company)+')':''}`).join(', ')}${o.inbound.status?' · '+esc(o.inbound.status):''}</p>`:''}<pre class="purchase-json" id="purchase-preview" hidden></pre><div class="form-actions">${!p.state||p.state==='failed'?`<button type="button" class="quiet" data-purchase-preview="${esc(o.id)}">Taobao тооцоо харах</button>${o.paid?`<button type="button" class="primary" data-purchase-create="${esc(o.id)}">Taobao-д захиалах</button>`:''}`:''}${p.state==='created'?`<button type="button" class="quiet" data-purchase-track="${esc(o.id)}">Хүргэлт шалгах</button>`:''}${p.state==='review'?`<button type="button" class="primary" data-purchase-resolve="${esc(o.id)}" data-outcome="created">Үүссэн · дугаар оруулах</button><button type="button" class="quiet" data-purchase-resolve="${esc(o.id)}" data-outcome="failed">Үүсээгүй</button>`:''}${['confirmed','shipping'].includes(o.status)?`<button type="button" class="quiet" data-tracking-add="${esc(o.id)}">Tracking гараар нэмэх</button>`:''}</div>${!o.paid?'<p class="muted">Төлбөр орсны дараа захиална.</p>':''}</section>`;}
function supplierHealthPanel(){const h=data.supplier_health;if(!h)return '';if(h.provider==='taoworld')return nativeSupplierHealthPanel(h);const b=h.budget,t=v=>v?adminTime(v*1000):'Бүртгэгдээгүй',status=v=>({unknown:'Батлагдаагүй',fresh:'Шинэ',published:'Шинэчилсэн',building:'Бэлтгэж байна',failed:'Алдаатай',disabled:'Идэвхгүй',busy:'Ажиллаж байна',cooldown:'Түр хүлээж байна',unavailable:'Боломжгүй'}[v]||v);return `<section class="panel integration-card" id="supplier-health"><h2>Каталогийн кэш ба API төсөв</h2><p>Өнөөдөр (UTC): <strong>${b.used} / ${b.limit}</strong> хүсэлт · үлдсэн ${b.remaining}<br>Захиалгад нөөцөлсөн: ${b.checkout_reserve} · Арын шинэчлэл: ${b.background_used} / ${b.background_limit}</p><p>Шинэчлэх мөчлөг: ${Math.round(h.refresh_interval/360)/10} цаг · Бэлтгэж буй ангилал: ${h.building_categories} · Алдаа: ${h.errors}</p><p>Сүүлд ажилласан: ${t(h.last_run)} · ${esc(status(h.status))}<br>Сүүлд амжилттай: ${t(h.last_success)}<br>Cron: ${t(h.cron_last_run)} · ${esc(status(h.cron_status))}</p>${h.cron_overdue?'<p class="error">Cron-ийн сүүлийн 30 минутын ажиллагаа батлагдаагүй. Hosting-ийн 10 минут тутмын тохиргоог шалгана уу.</p>':''}<p class="muted">Нийлүүлэгчийн дансны бодит үлдэгдэл биш, GOStore-ийн өдрийн төсөв. Захиалга болон шинэ нэхэмжлэл үүсгэхэд 2 минутаас хуучин үнэ, үлдэгдлийг дахин шалгана.</p></section>`;}
function integrations(){if(data.shipping?.catalog_provider==='taoworld')return nativeIntegrations();return `${taoworldDirectSettings()}${supplierHealthPanel()}${supplierIntegrationSettings()}${taobaoBuyerSettings()}`+`<div class="note">${data.qpay.enabled?'QPay идэвхтэй. Бодит захиалгын хүргэлт орсон нийт үнийг баталгаажуулж “Үнийн саналтай” төлөвт оруулна. Хэрэглэгч хүсэлтээсээ QR нэхэмжлэл нээж төлнө.':'QPay төлбөр авах горим идэвхгүй байна.'}</div><div class="integration-grid"><section class="panel integration-card"><span class="connection-icon">Q</span><h2>QPay Merchant V2</h2><p>QR нэхэмжлэлээр төлбөр хүлээн авах. Төлөгдсөн эсэхийг QPay серверийн хариугаар баталгаажуулна.</p><ul><li>Client ID / Client secret</li><li>Invoice code</li><li>HTTPS callback хаяг</li><li>Төлбөрийг callback-аар баталгаажуулна</li></ul><span class="tag ${data.qpay.enabled?'green':'yellow'}">${data.qpay.enabled?'Тохиргоотой · '+esc(data.qpay.environment):'Идэвхгүй'}</span></section><section class="panel integration-card"><span class="connection-icon">↗</span><h2>Нийлүүлэгч / Карго</h2><p>Taobao барааны хайлт, зураг, хувилбар, үнийг OT Commerce-оос уншина. Нийлүүлэгчид худалдан авах болон каргоны явц шинэчлэхийг админ гүйцэтгэнэ.</p><ul><li>Хайлт ба хуудсаар ачаалах</li><li>6 цагийн мэдээлэл хадгалалт</li><li>Өдрийн дуудлагын лимит: ханш ба карго хэсэгт</li></ul><span class="tag gray">OT Commerce · Taobao</span></section></div><section class="panel integration-card"><h3>Түлхүүрүүд серверт хадгалагдана</h3><p>Серверийн <code>server/config.local.php</code> файлд тохируулна. Энэ файл GitHub болон frontend JavaScript-д орохгүй. Админ дэлгэц нууц түлхүүрийг харуулахгүй. Байршуулалтын заавар repository-ийн README-д бий.</p></section>`;}
function render(){history.replaceState(null,'','#'+page);$('#mobile-admin-page').innerHTML=Object.entries(titles).map(([key,title])=>`<option value="${key}" ${key===page?'selected':''}>${esc(title)}</option>`).join('');document.querySelectorAll('nav [data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});$('#page-title').textContent=titles[page];$('#new-count').textContent=data.orders.filter(o=>o.status==='new').length;$('#content').innerHTML=window.AdminExtra?.pages[page]?AdminExtra.pages[page].html():page==='reviews'?'<section class="panel" id="admin-reviews"><p>Ачаалж байна…</p></section>':page==='customers'?customersPage():page==='overview'?overview():page==='products'?productList():page==='integrations'?integrations():page==='shipping'?shippingSettings():page==='warehouse'?warehouseSettings():page==='security'?adminSecuritySettings():page==='messages'?adminMessages():ordersList();if(page==='reviews')loadAdminReviews();if(page==='messages'){syncMessageForm($('#message-form'));loadAdminMessages();loadPromoPopup();}if(page==='customers')loadCustomers();window.AdminExtra?.afterRender(page);}
// Taobao Global returns here with an OAuth code after the admin signs in.
async function taobaoOAuthReturn(){const q=new URLSearchParams(location.search);if(!q.has('taobao_oauth'))return;history.replaceState(null,'',location.pathname);const code=q.get('code');if(!code){const keys=[...q.keys()].filter(k=>k!=='taobao_oauth'),reason=(q.get('error_description')||q.get('error')||q.get('message')||'').slice(0,200);toast('Taobao холболт цуцлагдсан'+(reason?': '+reason:'.')+' Ирсэн параметр: '+(keys.join(', ')||'байхгүй'));return;}try{data.taobao_buyer=(await api('taobao-buyer-connect',{code})).taobao_buyer;toast('Taobao данс холбогдлоо');page='integrations';render();}catch(e){toast(e.message);}}
async function taobaoAction(b){
  if(b.hasAttribute('data-taobao-connect')){location.assign((await api('taobao-buyer-authorize',{})).url);return true;}
  if(b.hasAttribute('data-taobao-disconnect')){if(!confirm('Taobao дансыг салгах уу? Автомат худалдан авалт зогсоно.'))return true;data.taobao_buyer=(await api('taobao-buyer-disconnect',{})).taobao_buyer;render();return true;}
  const id=b.dataset.purchasePreview||b.dataset.purchaseCreate||b.dataset.purchaseTrack||b.dataset.purchaseResolve||b.dataset.trackingAdd;if(!id)return false;
  if(b.dataset.purchasePreview){const r=await api('taobao-purchase-preview',{id});const pre=$('#purchase-preview');pre.textContent=r.render;pre.hidden=false;return true;}
  let r;if(b.dataset.purchaseCreate){if(!confirm(id+' захиалгыг Taobao-д бодит мөнгөөр захиалах уу?'))return true;r=await api('taobao-purchase-create',{id});}
  else if(b.dataset.purchaseTrack)r=await api('taobao-purchase-track',{id});
  else if(b.dataset.trackingAdd){const number=prompt('Хятад доторх tracking дугаар');if(!number)return true;r=await api('taobao-purchase-tracking-add',{id,number:number.trim(),company:(prompt('Тээврийн компани (заавал биш)')||'').trim()});}
  else{const body={id,outcome:b.dataset.outcome};if(body.outcome==='created'){body.provider_order_id=prompt('Taobao Global дээрх захиалгын дугаар');if(!body.provider_order_id)return true;}r=await api('taobao-purchase-resolve',body);}
  data.orders=data.orders.map(o=>o.id===id?r.order:o);editOrder(id);toast(r.order.purchase?.state==='failed'?'Taobao захиалга амжилтгүй':'Шинэчлэгдлээ');return true;
}
addEventListener('click',async e=>{const b=e.target.closest('[data-taobao-connect],[data-taobao-disconnect],[data-purchase-preview],[data-purchase-create],[data-purchase-track],[data-purchase-resolve],[data-tracking-add]');if(!b)return;e.stopImmediatePropagation();b.disabled=true;try{await taobaoAction(b);}catch(err){toast(err.message);}finally{b.disabled=false;}},true);
addEventListener('change',async e=>{if(!e.target.matches('[data-taobao-auto]'))return;try{data.taobao_buyer=(await api('taobao-buyer-auto',{enabled:e.target.checked})).taobao_buyer;toast(e.target.checked?'Автомат худалдан авалт асав':'Автомат худалдан авалт унтрав');}catch(err){e.target.checked=!e.target.checked;toast(err.message);}});
async function refresh(){data=await api('dashboard');$('#admin-email').textContent=data.email;$('#login-screen').hidden=true;$('#app').hidden=false;render();taobaoOAuthReturn();}
let adminTrackingView=0;
function modal(title,html){adminTrackingView++;$('#editor-title').textContent=title;$('#editor-body').innerHTML=html;if(!$('#editor').open)$('#editor').showModal();}
function adminTrackingNames(o){const profiles=Object.values(data.warehouse_profiles||{});return Object.fromEntries(['erenhot','ulaanbaatar'].map(role=>[role,profiles.find(w=>w.location===(o.warehouse_locations?.[role]||role))?.name]));}
async function showAdminTracking(id){
  modal(id,'<p class="muted" role="status">Ачааны явцыг уншиж байна…</p>');const request=adminTrackingView;
  try{
    const {order:o}=await api('admin-order&'+new URLSearchParams({id}));
    if(request!==adminTrackingView||!$('#editor').open)return;
    modal(o.id,`<p class="tracking-order-title">${esc(o.title)}</p>${OrderTracking.html(o,{names:adminTrackingNames(o)})}<div class="form-actions"><button type="button" class="quiet" data-admin-track="${esc(o.id)}">Явц шинэчлэх ↻</button><button type="button" class="quiet" data-close>Хаах</button></div>`);
  }catch(error){if(request===adminTrackingView&&$('#editor').open){if($('#app').hidden){$('#editor').close();return;}modal(id,`<p class="error" role="alert">${esc(error.message)}</p><button class="quiet" data-admin-track="${esc(id)}">Дахин оролдох</button>`);}}
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-admin-track]');if(!b)return;b.disabled=true;try{await showAdminTracking(b.dataset.adminTrack);}finally{b.disabled=false;}});
function editProduct(id){const p=data.products.find(x=>x.id===id)||{id:'',name:'',description:'',category:'home',type:'local',price:0,stock:0,image:'chair',variants:['Стандарт'],active:false,demo:true};modal(p.id?'Бараа засах':'Шинэ бараа',`<form id="product-form"><input type="hidden" name="id" value="${esc(p.id)}"><div class="form-grid"><label class="full">Барааны нэр<input name="name" value="${esc(p.name)}" maxlength="150" required></label><label>Ангилал<select name="category">${Object.entries(categories).map(([k,v])=>`<option value="${k}" ${k===p.category?'selected':''}>${v}</option>`).join('')}</select></label><label>Төрөл<select name="type"><option value="local" ${p.type==='local'?'selected':''}>Бэлэн бараа</option><option value="china" ${p.type==='china'?'selected':''}>Хятадаас захиалах</option></select></label><label>Үнэ (₮)<input type="number" name="price" min="0" max="100000000" step="1" value="${p.price}" required></label><label>Үлдэгдэл (ширхэг)<input type="number" name="stock" min="0" max="1000000" step="1" value="${p.stock}" required></label><label>Зураг<select name="image">${[...new Set(['chair','headphones','backpack','sneakers','watch','lamp','skincare','living',p.image])].map(k=>`<option ${k===p.image?'selected':''}>${k}</option>`).join('')}</select></label><label class="full">Өөрийн зураг оруулах (5 MB / 12 MP хүртэл)<input id="image-upload" type="file" accept="image/jpeg,image/png,image/webp"><small id="upload-status">JPEG, PNG, WebP · хадгалахад JPEG болгоно</small></label><label>Хувилбарууд (таслалаар)<input name="variants" value="${esc(p.variants.join(', '))}" required></label><label class="full">Тайлбар<textarea name="description" maxlength="3000" required>${esc(p.description)}</textarea></label></div><label class="check"><input type="checkbox" name="active" ${p.active?'checked':''}>Дэлгүүрт нийтлэх</label><label class="check"><input type="checkbox" name="demo" ${p.demo?'checked':''}>Жишээ бараа (QPay төлбөр авахгүй)</label><p class="muted">Үлдэгдэл нь лавлах тоо. Хүсэлт хүлээн авахад автоматаар хасагдахгүй.</p><p class="error" id="form-error" role="alert"></p><div class="form-actions">${p.id?`<button class="quiet danger" type="button" data-delete-product="${esc(p.id)}">Устгах</button>`:""}<button class="quiet" type="button" data-close>Болих</button><button class="primary">Хадгалах</button></div></form>`);}
// Final bill, refunds and the refund form (bill reduced after the customer paid).
function adminBillingHtml(o){const b=o.billing;if(!b||!o.settlement)return '';return `<div class="note">Эцсийн тооцоо: нийт ${money(b.total)} · төлсөн ${money(b.paid)}${b.refunded?` (буцаасан ${money(b.refunded)})`:''} · үлдэгдэл ${money(b.due)}${o.settlement.early?' · Эрээнээс гарахад автоматаар':''}${b.refund_due>0?`<br><strong>Буцаах: ${money(b.refund_due)}</strong> — дансаар шилжүүлээд доор бүртгэнэ. Бүртгэх хүртэл бараа хүлээлгэн өгөхгүй.`:''}</div>${b.refund_due>0?`<form id="refund-form" class="form-grid"><input type="hidden" name="id" value="${esc(o.id)}"><label>Буцаасан дүн · ₮<input name="amount" type="number" min="1" max="${b.refund_due}" step="1" value="${b.refund_due}" required></label><label>Тайлбар (данс, гүйлгээ)<input name="note" maxlength="500" required></label><button class="primary">Буцаалт бүртгэх</button></form>`:''}`;}
function editOrder(id){const o=data.orders.find(x=>x.id===id);if(!o)return;modal(o.id,`${OrderTracking.html(o,{names:adminTrackingNames(o)})}<div class="details"><div><small>Хэрэглэгч</small>${esc(o.customer)}</div><div><small>Утас</small>${esc(o.phone)}</div><div><small>Хүсэлт</small>${esc(o.title)}</div><div><small>Төлбөр</small>${o.paid?'QPay-ээр баталгаажсан':'Төлбөр хүлээн аваагүй'}</div></div><div class="order-items">${['link','supplier'].includes(o.type)?`<a href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">${esc(o.url)}</a><br>${esc(o.variant)} · ${o.qty} ширхэг`:o.items.map(i=>`${i.url?`<a href="${esc(i.url)}" target="_blank" rel="noopener noreferrer">${esc(i.name)}</a>`:esc(i.name)} / ${esc(i.variant)} × ${i.qty} · ${i.unit_cny?esc(i.unit_cny)+'¥ · SKU '+esc(i.sku)+' · ':''}${money(i.price*i.qty)}`).join('<br>')}${o.type==='checkout'?`<br><strong>Сагсаар шууд захиалга</strong> · ${o.paid?'урьдчилгаа төлөгдсөн':o.payment_due?'төлөх хугацаа '+esc(new Date(o.payment_due).toLocaleString('mn-MN')):''}${o.cancel_reason==='payment_timeout'?' · хугацаа дууссан тул автоматаар цуцлагдсан':''}`:''}<br>${esc(o.notes||'Нэмэлт хүсэлтгүй')}</div>${o.batch_id?`<div class="note">Тээврийн багц: <strong>${esc(o.batch_id)}</strong> · Бүрэлдэхүүн, явцыг агуулахын панелаас удирдана.</div>`:''}${adminBillingHtml(o)}${o.fulfillment?`<div class="note">Авах хэлбэр: ${o.fulfillment.method==='pickup'?'Агуулахаас':'Хүргэлтээр'} · ${esc(o.fulfillment.contact_phone)}<br>${esc(o.fulfillment.address)}</div>`:''}${warehouseAssignment(o)}${warehouseLabel(o)}${o.demo?'<div class="note">Жишээ бараатай хүсэлт тул QPay төлбөр авахгүй.</div>':''}${o.invoice?`<div class="note">Нэхэмжлэлийн төлөв: ${esc(o.invoice.state)}. Үнийн дүн түгжигдсэн.</div>`:''}${o.supplier?`<div class="note">${o.supplier.id?.startsWith('tb-')?'Taobao':'1688'} барааны лавлах дүн: ${esc(o.supplier.goods_cny)}¥ · Хувилбар: ${esc(o.supplier.sku)}. Нийлүүлэгчид худалдан авалтыг оператор баталгаажуулна.</div>`:""}${!o.invoice?quoteCalculator(o):""}<form id="order-form"><input type="hidden" name="id" value="${esc(o.id)}"><div class="form-grid"><label>Захиалгын төлөв<select name="status">${Object.entries(statuses).filter(([key])=>key===o.status||(!(o.batch_id||o.fulfillment)&&!['erenhot_ready','ulaanbaatar_unsorted','ready_pickup','ready_delivery','out_for_delivery'].includes(key))).map(([k,v])=>`<option value="${k}" ${o.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Хүргэлт орсон нийт санал (₮)<input type="number" name="amount" value="${o.amount}" min="0" max="100000000" step="1" required ${o.invoice?'readonly':''}></label><label class="full">Админы дотоод тэмдэглэл<textarea name="internal_note" maxlength="2000">${esc(o.internal_note)}</textarea></label></div><p class="error" id="form-error" role="alert"></p><div class="form-actions"><button class="primary">Өөрчлөлт хадгалах</button></div></form>${purchasePanel(o)}${window.AdminExtra?.orderPanel(o)||''}`);}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;query='';statusFilter='all';Object.assign(customerState,{q:'',filter:'active',offset:0});render();}if(b.hasAttribute('data-new-warehouse'))newWarehouse();if(b.hasAttribute('data-new'))editProduct('');if(b.dataset.product)editProduct(b.dataset.product);if(b.dataset.deleteProduct)deleteProduct(b.dataset.deleteProduct);if(b.dataset.order)editOrder(b.dataset.order);if(b.hasAttribute('data-copy-warehouse')){try{await navigator.clipboard.writeText($('#warehouse-label').value);toast('Агуулахын мэдээллийг хууллаа');}catch{$('#warehouse-label').select();toast('Мэдээллийг сонголоо. Ctrl+C дарж хуулна уу.');}}if(b.hasAttribute('data-close')||b.id==='close-editor')$('#editor').close();if(b.hasAttribute('data-refresh')){try{await refresh();toast('Шинэчиллээ');}catch(e){toast(e.message);}}});
document.addEventListener('input',e=>{if(e.target.id==='list-search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#list-search').focus();$('#list-search').setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='mobile-admin-page'){page=e.target.value;query='';statusFilter='all';Object.assign(customerState,{q:'',filter:'active',offset:0});render();}if(e.target.id==='status-filter'){statusFilter=e.target.value;render();}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=new FormData(f),button=f.querySelector('button[type="submit"],button.primary');button.disabled=true;try{if(f.id==='warehouse-create-form'){await api('warehouse-create',Object.fromEntries(fd));$('#editor').close();await refresh();toast('Агуулах болон менежерийн эрх үүслээ');}else if(f.getAttribute('id')==='warehouse-assign-form'){await api('warehouse-assign-order',Object.fromEntries(fd));await refresh();editOrder(fd.get('id'));toast('Агуулах оноолоо');}else if(f.getAttribute('id')==='refund-form'){const d=await api('order-refund',{id:fd.get('id'),amount:Number(fd.get('amount')),note:fd.get('note')});const i=data.orders.findIndex(x=>x.id===d.order.id);if(i>=0)data.orders[i]=d.order;editOrder(d.order.id);toast('Буцаалт бүртгэгдлээ');}else if(f.getAttribute('id')==='customer-form'){await api('admin-customer-save',{...Object.fromEntries(fd),expected:JSON.parse(f.dataset.expected)});$('#editor').close();await loadCustomers();toast('Хэрэглэгчийн мэдээлэл хадгалагдлаа');}else if(f.id==='admin-password-form'){await api('admin-password-change',Object.fromEntries(fd));f.reset();toast('Нууц үг солигдлоо. Бусад төхөөрөмжийн нэвтрэлт хаагдлаа.');}else if(f.matches('[data-warehouse-profile]')){await api('warehouse-profile-save',{...Object.fromEntries(fd),location:f.dataset.warehouseProfile,...(f.elements.active?{active:fd.has('active')}:{})});await refresh();toast('Агуулахын мэдээлэл хадгалагдлаа');}else if(f.getAttribute('id')==='product-delete-form'){await api('product-delete',Object.fromEntries(fd));$('#editor').close();await refresh();toast('Бараа устгагдлаа');}else if(f.matches('[data-warehouse-account]')){const b=Object.fromEntries(fd);b.location=f.dataset.warehouseAccount;b.enabled=fd.has('enabled');await api('warehouse-account-save',b);f.elements.password.value='';await refresh();toast('Агуулахын эрх хадгалагдлаа');}else if(f.id==='shipping-form'){const b=Object.fromEntries(fd);for(const k of shippingNumbers)b[k]=Number(b[k]);b.api_daily_limit=Number(b.api_daily_limit);b.supplier_enabled=fd.has('supplier_enabled');b.image_search_enabled=fd.has('image_search_enabled');await api('shipping-save',b);await refresh();toast('Ханш, каргоны тохиргоо хадгалагдлаа');}else if(f.id==='message-form'){await sendAdminMessage(f,fd);}else if(f.id==='quote-form'){const b=Object.fromEntries(fd);for(const k of ['goods_cny','domestic_cny','weight_kg','volume_m3'])b[k]=Number(b[k]);const r=await api('shipping-calculate',b);const orderForm=$('#order-form');orderForm.elements.amount.value=r.quote.total;orderForm.dataset.quoteInputs=JSON.stringify(b);$('#quote-result').textContent=quoteText(r.quote)+' · Захиалгын өөрчлөлт хадгалах товчийг дарна уу.';}else if(f.getAttribute('id')==='login-form'){await api('session');await api('login',Object.fromEntries(fd));f.password.value='';await refresh();}else if(f.getAttribute('id')==='product-form'){const p=Object.fromEntries(fd);p.price=Number(p.price);p.stock=Number(p.stock);p.active=fd.has('active');p.demo=fd.has('demo');p.variants=p.variants.split(',').map(s=>s.trim()).filter(Boolean);await api('product-save',p);$('#editor').close();await refresh();toast('Бараа хадгалагдлаа');}else if(f.getAttribute('id')==='order-form'){const o=Object.fromEntries(fd);o.amount=Number(o.amount);if(f.dataset.quoteInputs)o.quote_inputs=JSON.parse(f.dataset.quoteInputs);await api('order-update',o);$('#editor').close();await refresh();toast('Захиалга шинэчлэгдлээ');}}catch(e){(f.querySelector('.error')||$('#form-error')).textContent=e.message;}finally{button.disabled=false;}});
$('#logout').addEventListener('click',async()=>{try{await api('logout',{});location.reload();}catch(e){toast(e.message);}});
(async()=>{try{const s=await api('session');$('#setup-note').textContent=s.configured?'Эрх бүхий администраторт зориулсан хэсэг.':'Анхны админ тохируулаагүй. README-ийн “Админ эрх” хэсгийн дагуу серверт тохируулна уу.';if(s.authenticated)await refresh();}catch(e){$('#login-error').textContent=e.message;$('#setup-note').textContent='PHP 8.2+, PDO SQLite, mbstring шаардлагатай.';}})();

document.addEventListener('change',async e=>{if(e.target.id!=='image-upload'||!e.target.files[0])return;const form=e.target.closest('form'),button=form.querySelector('button.primary');button.disabled=true;try{const fd=new FormData();fd.append('image',e.target.files[0]);const response=await fetch('../api/index.php?action=image-upload',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf},body:fd});const result=await response.json();if(!response.ok)throw Error(result.error);const select=form.elements.image;const option=new Option('Оруулсан зураг',result.image,true,true);select.add(option);$('#upload-status').textContent='Зураг орууллаа. Бараагаа хадгална уу.';}catch(err){$('#form-error').textContent=err.message;}finally{button.disabled=false;}});

function nativeSupplierHealthPanel(h){const b=h.budget;return `<section class="panel integration-card" id="supplier-health"><h2>TaoWorld каталогийн кэш ба API төсөв</h2><p>Каталог: <strong>${h.enabled?'Идэвхтэй':'Идэвхгүй'}</strong></p><p>Өнөөдөр (UTC): <strong>${b.used} / ${b.limit}</strong> хүсэлт · үлдсэн ${b.remaining}<br>Захиалгад нөөцөлсөн: ${b.checkout_reserve}</p><p>Хайлтын кэш: ${h.search_ttl/60} минут · Барааны дэлгэрэнгүй: ${h.detail_ttl/60} минут · Зурагт хайлт: ${h.image_ttl/60} минут</p><p class="muted">Мэдээллийг хүсэлтээр шинэчилнэ. Захиалга болон шинэ нэхэмжлэл үүсгэхэд ${h.checkout_ttl/60} минутаас хуучин үнэ, үлдэгдлийг дахин шалгана. Худалдан авалтын cron төлөвийг TaoWorld холболтын хэсэгт харуулна.</p></section>`;}

function nativeIntegrations(){return `${taoworldDirectSettings()}${supplierHealthPanel()}<section class="panel integration-card"><h2>QPay Merchant V2</h2><p>Хэрэглэгчийн төлбөрийг QPay серверээр баталгаажуулна. Үүний дараа TaoWorld худалдан авалт дээрх тохиргооны дагуу боловсруулагдана.</p><span class="tag ${data.qpay.enabled?'green':'yellow'}">${data.qpay.enabled?'Идэвхтэй · '+esc(data.qpay.environment):'Идэвхгүй'}</span></section><section class="panel integration-card"><h2>Каталог ба хүргэлт</h2><p>Бараа болон зурагт хайлтыг TaoWorld шууд API-аас уншина. Барааны нэр англи хэлээр харагдана. Захиалах үед үнэ, SKU, үлдэгдлийг сервер дахин шалгана.</p><p>Эрээн рүүх нийлүүлэгчийн захиалга, төлбөр, тээврийн дугаарыг захиалгын дэлгэрэнгүйд харуулна. Ханш, каргоны тариф, API хязгаарыг «Ханш ба карго» хэсгээс удирдана.</p></section>`;}
async function loadAdminReviews(number=1){
 const host=document.querySelector('#admin-reviews');if(!host)return;
 try{const result=await api('reviews-admin&page='+number);if(!host.isConnected)return;host.innerHTML=`<div class="panel-heading"><h3>GOStore хэрэглэгчдийн үнэлгээ</h3><button class="quiet" data-reviews-page="1">Шинэчлэх</button></div>${result.reviews.map(r=>`<article style="padding:20px;border-top:1px solid #ddd"><strong>${esc(r.title)}</strong><p>${esc(r.product)} · ${r.rating} / 5 · ${esc(r.author)} · ${r.status==='hidden'?'Нуусан':'Нийтлэгдсэн'}</p><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(r.comment)}</p><div style="display:flex;gap:8px;flex-wrap:wrap">${r.status==='visible'?r.photos.map(url=>`<a href="${esc(url)}" target="_blank" rel="noopener"><img src="${esc(url)}" style="width:90px;height:90px;object-fit:cover" alt="Сэтгэгдлийн зураг" loading="lazy"></a>`).join(''):''}</div>${r.reports?`<p><b>${r.reports} мэдээлэл ирсэн</b></p><ul>${r.reasons.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul>`:''}<button class="quiet" data-review-moderate="${r.id}" data-status="${r.status==='hidden'?'visible':'hidden'}">${r.status==='hidden'?'Дахин харуулах':'Нуух'}</button></article>`).join('')||'<p style="padding:20px">Сэтгэгдэл хараахан алга.</p>'}<div class="panel-heading">${number>1?`<button class="quiet" data-reviews-page="${number-1}">Өмнөх</button>`:''}<span>${number}-р хуудас</span>${result.more?`<button class="quiet" data-reviews-page="${number+1}">Дараах</button>`:''}</div>`;host.dataset.page=number;}
 catch(e){host.textContent=e.message;}
}
// Registered customers: searched, filtered and paged on the server; profiles edited in the dialog.
const customerFilters={active:'Бүх идэвхтэй бүртгэл',phone:'Утсаар нэвтэрдэг',email:'Имэйлээр нэвтэрдэг',deleted:'Устгагдсан бүртгэл'};
const customerLogins={phone:['Утас · PIN',''],email:['Имэйл',''],both:['Имэйл + утас','green'],none:['Нэвтрэх эрхгүй','yellow'],deleted:['Устгагдсан','gray']};
const customerState={q:'',filter:'active',offset:0,request:0};
const ubDay=v=>v?new Date(v).toLocaleDateString('sv-SE',{timeZone:'Asia/Ulaanbaatar'}):'—';
const customerLogin=c=>`<span class="tag ${customerLogins[c.login][1]}">${customerLogins[c.login][0]}</span>`;
function customersPage(){const s=customerState;return `<div class="page-intro"><div><p class="eyebrow">БҮРТГЭЛТЭЙ ХЭРЭГЛЭГЧИД</p><h2>Хэрэглэгчийн жагсаалт</h2><p>Сайт болон аппаар бүртгүүлсэн хэрэглэгчдийн мэдээлэл, хаяг, захиалга.</p></div></div><div class="warehouse-summary customer-summary" id="customer-stats"></div><div class="toolbar orders-toolbar"><input id="customer-search" type="search" aria-label="Хэрэглэгч хайх" placeholder="Нэр, имэйл, утасны дугаараар хайх…" maxlength="100" value="${esc(s.q)}"><select id="customer-filter" aria-label="Нэвтрэх аргаар шүүх">${Object.entries(customerFilters).map(([k,v])=>`<option value="${k}" ${k===s.filter?'selected':''}>${v}</option>`).join('')}</select><button class="quiet" type="button" data-customers-reload>↻ Шинэчлэх</button></div><section class="panel orders-panel" id="admin-customers" aria-live="polite"><p class="empty">Хэрэглэгчдийг ачаалж байна…</p></section>`;}
function customerTable(r){
 const s=customerState,rows=r.customers,filtered=s.q!==''||s.filter!=='active',heading=`<div class="panel-heading"><h3>${esc(customerFilters[s.filter])}</h3><span class="muted">${r.total} хэрэглэгч</span></div>`;
 if(!rows.length)return heading+`<div class="empty"><h3>${filtered?'Тохирох хэрэглэгч алга':'Бүртгэлтэй хэрэглэгч хараахан алга'}</h3>${filtered?'Хайлт эсвэл шүүлтүүрээ өөрчилнө үү.':'Сайт болон аппаар бүртгүүлсэн хэрэглэгчид энд харагдана.'}</div>`;
 const pager=r.total>r.page_size?`<div class="customer-pager"><span class="muted">${r.offset+1}–${r.offset+rows.length} / ${r.total}</span><div>${r.offset>0?`<button class="quiet" type="button" data-customers-offset="${Math.max(0,r.offset-r.page_size)}">← Өмнөх</button>`:''}${r.more?`<button class="quiet" type="button" data-customers-offset="${r.offset+r.page_size}">Дараах →</button>`:''}</div></div>`:'';
 return heading+`<div class="table-wrap customers-table-wrap"><table class="customers-table" aria-label="Хэрэглэгчийн жагсаалт"><colgroup><col class="customer-col-main"><col class="customer-col-phone"><col class="customer-col-login"><col class="customer-col-orders"><col class="customer-col-created"><col class="customer-col-action"></colgroup><thead><tr><th scope="col">Хэрэглэгч</th><th scope="col">Утас</th><th scope="col">Нэвтрэх арга</th><th scope="col">Захиалга</th><th scope="col">Бүртгүүлсэн</th><th scope="col"><span class="admin-sr-only">Үйлдэл</span></th></tr></thead><tbody>${rows.map(c=>`<tr><td class="customer-main"><strong>${esc(c.name)}</strong><small>${esc(c.email||(c.login==='deleted'?'Хувийн мэдээлэл устсан':'Имэйлгүй'))}</small></td><td class="customer-phone" data-label="Утас">${esc(c.phone||'—')}</td><td class="customer-login" data-label="Нэвтрэх арга">${customerLogin(c)}</td><td class="customer-order-count" data-label="Захиалга"><strong>${c.orders}</strong><small>${c.last_order?'Сүүлд '+ubDay(c.last_order):'Захиалаагүй'}</small></td><td class="customer-created" data-label="Бүртгүүлсэн"><time datetime="${esc(c.created)}">${ubDay(c.created)}</time></td><td class="customer-action"><button class="quiet" type="button" data-customer="${esc(c.id)}" aria-label="${esc(c.name)} · ${c.login==='deleted'?'дэлгэрэнгүй харах':'мэдээлэл засах'}">${c.login==='deleted'?'Харах →':'Засах →'}</button></td></tr>`).join('')}</tbody></table></div>${pager}`;
}
async function loadCustomers(){
 const host=$('#admin-customers');if(!host)return;const s=customerState,request=++s.request;
 try{
  const r=await api('admin-customers&'+new URLSearchParams({q:s.q,filter:s.filter,offset:s.offset}));if(request!==s.request||!host.isConnected)return;
  if(!r.customers.length&&s.offset>0){s.offset=0;return loadCustomers();}
  const t=r.stats;$('#customer-stats').innerHTML=`<span><strong>${t.active}</strong> бүртгэлтэй</span><span><strong>${t.week}</strong> сүүлийн 7 хоногт</span><span><strong>${t.phone}</strong> утсаар нэвтэрдэг</span><span><strong>${t.email}</strong> имэйлээр нэвтэрдэг</span>${t.deleted?`<span><strong>${t.deleted}</strong> устгагдсан</span>`:''}`;
  host.innerHTML=customerTable(r);
 }catch(e){if(request===s.request&&host.isConnected)host.innerHTML=`<p class="error customer-error" role="alert">${esc(e.message)}</p>`;}
}
async function editCustomer(id){
 modal('Хэрэглэгч','<p class="muted" role="status">Хэрэглэгчийн мэдээллийг уншиж байна…</p>');const view=adminTrackingView;
 try{const r=await api('admin-customer&'+new URLSearchParams({id}));if(view===adminTrackingView&&$('#editor').open)customerEditor(r);}
 catch(e){if(view!==adminTrackingView||!$('#editor').open)return;if($('#app').hidden){$('#editor').close();return;}modal('Хэрэглэгч',`<p class="error" role="alert">${esc(e.message)}</p><div class="form-actions"><button class="quiet" type="button" data-close>Хаах</button><button class="quiet" type="button" data-customer="${esc(id)}">Дахин оролдох</button></div>`);}
}
function customerEditor({customer:c,addresses,orders}){
 const deleted=c.login==='deleted',pin=c.login_phone!=='';
 const form=deleted?'<div class="note">Хэрэглэгч бүртгэлээ устгасан. Захиалгын түүх хадгалагдсан ч хувийн мэдээлэл устсан тул засахгүй.</div>':`<form id="customer-form"><input type="hidden" name="id" value="${esc(c.id)}"><div class="form-grid"><label class="full">Нэр<input name="name" maxlength="100" value="${esc(c.name)}" autocomplete="off" required></label><label>Имэйл${c.email?`<input name="email" type="email" maxlength="200" value="${esc(c.email)}" autocomplete="off" required><small>Хэрэглэгч энэ имэйлээр нэвтэрнэ.</small>`:`<input value="Имэйлгүй" aria-label="Имэйл" disabled><small>Утсаар бүртгүүлсэн тул имэйл нэмэхгүй.</small>`}</label><label>Холбоо барих утас<input name="phone" type="tel" maxlength="30" value="${esc(c.phone)}" autocomplete="off" ${pin?'readonly':''}><small>${pin?'Нэвтрэх утас. Хэрэглэгч өөрөө SMS-ээр баталгаажуулж солино.':'Хоосон үлдээж болно.'}</small></label></div><p class="error" role="alert"></p><div class="form-actions"><button class="quiet" type="button" data-close>Болих</button><button class="primary" type="submit">Хадгалах</button></div></form>`;
 const addressList=addresses.length?addresses.map(a=>`<div class="customer-address"><strong>${esc(a.label)}</strong>${a.is_default?' <span class="tag green">Үндсэн</span>':''}<p>${esc(a.address)}</p><small>${esc([a.recipient,a.phone].filter(Boolean).join(' · '))}</small></div>`).join(''):'<p class="muted">Хаяг хадгалаагүй.</p>';
 const orderList=orders.length?`<ul class="customer-orders-list">${orders.map(o=>`<li><div><strong>${esc(o.id)}</strong> ${tag(o.status)}<small>${esc(o.title)}</small></div><div class="customer-order-amount">${o.amount?money(o.amount):'Үнэ хүлээгдэж байна'}<small>${o.paid?'Төлөгдсөн':'Төлбөр хүлээгдэж байна'} · ${ubDay(o.created)}</small></div><button type="button" class="quiet" ${data.orders.some(x=>x.id===o.id)?`data-order="${esc(o.id)}"`:`data-admin-track="${esc(o.id)}"`}>Харах →</button></li>`).join('')}</ul>${c.orders>orders.length?`<p class="muted">Сүүлийн ${orders.length} захиалгыг харуулав · нийт ${c.orders}.</p>`:''}`:'<p class="muted">Захиалга хараахан алга.</p>';
 modal(deleted?'Устгагдсан бүртгэл':c.name,`<div class="details customer-details"><div><small>Нэвтрэх арга</small>${customerLogin(c)}</div><div><small>Захиалга</small>${c.orders}${c.last_order?' · сүүлд '+ubDay(c.last_order):''}</div><div><small>Бүртгүүлсэн</small>${esc(adminTime(c.created))}</div><div><small>Сүүлд шинэчилсэн</small>${esc(adminTime(c.updated))}</div><div class="full"><small>Бүртгэлийн ID</small><code>${esc(c.id)}</code></div></div>${form}<section class="customer-section"><h3>Хүргэлтийн хаяг</h3>${addressList}</section><section class="customer-section"><h3>Сүүлийн захиалгууд</h3>${orderList}</section>`);
 if(!deleted)$('#customer-form').dataset.expected=JSON.stringify({name:c.name,email:c.email,phone:c.phone});
}
let customerSearchTimer;
document.addEventListener('input',e=>{if(e.target.id!=='customer-search')return;clearTimeout(customerSearchTimer);customerSearchTimer=setTimeout(()=>{customerState.q=e.target.value.trim();customerState.offset=0;loadCustomers();},300);});
document.addEventListener('change',e=>{if(e.target.id!=='customer-filter')return;customerState.filter=e.target.value;customerState.offset=0;loadCustomers();});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.customer)editCustomer(b.dataset.customer);
 if(b.hasAttribute('data-customers-offset')){customerState.offset=Number(b.dataset.customersOffset);await loadCustomers();$('#admin-customers')?.scrollIntoView({block:'start'});}
 if(b.hasAttribute('data-customers-reload')){b.disabled=true;await loadCustomers();b.disabled=false;}
});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.reviewsPage)return loadAdminReviews(Number(b.dataset.reviewsPage));if(!b.dataset.reviewModerate)return;b.disabled=true;try{await api('review-moderate',{id:b.dataset.reviewModerate,status:b.dataset.status});await loadAdminReviews(Number(document.querySelector('#admin-reviews')?.dataset.page||1));}catch(err){toast(err.message);b.disabled=false;}});
// Customer messages: the inbox copy reaches every recipient (site bell, account page, app); phone pushes
// go to app users who allowed notifications, and promotions only to those who also allowed promotional pushes.
function messageLabels(){return {kinds:{service:'Үйлчилгээний мэдээлэл',promo:'Хямдрал, урамшуулал'},audiences:{all:'Бүх хэрэглэгч',active:'Идэвхтэй захиалгатай хэрэглэгчид',customer:'Нэг хэрэглэгч (утасны дугаараар)'}};}
function messageRequestId(){if(crypto.randomUUID)return crypto.randomUUID();return [...crypto.getRandomValues(new Uint8Array(16))].map(n=>n.toString(16).padStart(2,'0')).join('');}
function adminMessages(){const l=messageLabels(),opts=o=>Object.entries(o).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('');return `<section class="panel integration-card"><h2>Хэрэглэгчдэд мэдэгдэл илгээх</h2><p>Мэдэгдэл сайтын хонх, бүртгэлийн «Мэдэгдэл» хэсэг болон аппын мэдэгдлийн жагсаалтад харагдана. Утсанд push зөвхөн аппад мэдэгдэл зөвшөөрсөн хэрэглэгчдэд очно. Хямдралын мэдэгдлийг тусад нь зөвшөөрсөн хүмүүст л push-ээр илгээнэ.</p><form id="message-form" data-request="${messageRequestId()}"><div class="form-grid"><label>Төрөл<select name="kind">${opts(l.kinds)}</select></label><label>Хүлээн авагч<select name="audience">${opts(l.audiences)}</select></label><label class="full" data-message-phone hidden>Хэрэглэгчийн утасны дугаар<input name="phone" inputmode="tel" autocomplete="off" maxlength="30" placeholder="99112233"></label><label class="full">Гарчиг<input name="title" maxlength="80" required></label><label class="full">Мэдэгдэл<textarea name="body" maxlength="1000" required></textarea></label><label class="full">Холбоос (заавал биш)<input name="link" maxlength="200" placeholder="/help эсвэл https://gostore.mn/..."></label></div><p class="muted">Олон хүнд очих мэдэгдэлд хувийн мэдээлэл (утас, хаяг, төлбөрийн дүн) бүү бичээрэй. Илгээсэн мэдэгдлийг буцааж татах боломжгүй.</p><p id="message-preview" role="status"></p><p class="error" role="alert"></p><button class="primary" type="submit">Хүлээн авагчдыг шалгах</button></form></section><section class="panel integration-card" id="promo-admin"><h2>Сурталчилгааны popup</h2><p>Вэбийн нүүр хуудас болон апп нээгдэх үед гарна. Нэг төхөөрөмжид өдөрт нэг удаа харагдана; агуулгыг өөрчилбөл дахин гарна. Холбоос нь сайтын хуудас (/v/123456, /official-stores, /?q=цүнх) эсвэл https:// хаяг байна.</p><form id="promo-form"><label class="check"><input type="checkbox" name="enabled">Popup идэвхтэй</label><div class="form-grid"><label class="full">Зураг (JPEG, PNG, WebP · 5 MB хүртэл)<input type="file" id="promo-image-upload" accept="image/jpeg,image/png,image/webp"></label><input type="hidden" name="image"><div class="full promo-admin-image" hidden><img alt="Popup зураг"><button class="quiet" type="button" data-promo-image-remove>Зураг хасах</button></div><label class="full">Гарчиг<input name="title" maxlength="80"></label><label class="full">Тайлбар<textarea name="text" maxlength="300" rows="3"></textarea></label><label>Товчны бичиг<input name="button" maxlength="30" placeholder="Дэлгэрэнгүй"></label><label>Холбоос<input name="link" maxlength="500" placeholder="/v/123456 эсвэл https://…"></label><label>Эхлэх (заавал биш)<input type="datetime-local" name="starts"></label><label>Дуусах (заавал биш)<input type="datetime-local" name="ends"></label></div><p id="promo-status" role="status"></p><p class="error" role="alert"></p><button class="primary" type="submit">Popup хадгалах</button></form></section><section class="panel" id="admin-message-history"><p style="padding:20px">Ачаалж байна…</p></section>`;}
function syncMessageForm(f,reset){if(!f)return;const customer=f.elements.audience.value==='customer';f.querySelector('[data-message-phone]').hidden=!customer;f.elements.phone.required=customer;if(reset){delete f.dataset.confirmed;f.dataset.request=messageRequestId();$('#message-preview').textContent='';f.querySelector('button[type="submit"]').textContent='Хүлээн авагчдыг шалгах';}}
// First submit shows who will receive it; the second submit sends. Any edit asks again.
async function sendAdminMessage(f,fd){const b=Object.fromEntries(fd),key=JSON.stringify(b),out=$('#message-preview'),button=f.querySelector('button[type="submit"]');f.querySelector('.error').textContent='';if(b.audience!=='customer')delete b.phone;
 if(f.dataset.confirmed!==key){const p=await api('admin-message-preview',{kind:b.kind,audience:b.audience,...(b.phone?{phone:b.phone}:{})});f.dataset.confirmed=key;out.textContent=`${p.recipients} хэрэглэгчид очно. Утасны push: ${p.push_enabled?p.push_devices+' төхөөрөмж':'сервер дээр идэвхжээгүй'}. Илгээх бол дахин дарна уу.`;button.textContent='Баталгаажуулж илгээх';return;}
 const r=await api('admin-message-send',{...b,request_id:f.dataset.request});f.reset();syncMessageForm(f,true);toast(r.duplicate?'Энэ мэдэгдэл өмнө нь илгээгдсэн байна':`${r.message.recipients} хэрэглэгчид илгээлээ`);await loadAdminMessages();}
function messagePushText(p){const parts=[p.delivered&&p.delivered+' хүрсэн',p.queued&&p.queued+' илгээж буй',p.failed&&p.failed+' амжилтгүй'].filter(Boolean);return parts.join(' · ')||'—';}
async function loadAdminMessages(){const host=$('#admin-message-history');if(!host)return;const l=messageLabels();
 try{const r=await api('admin-messages');if(!host.isConnected)return;host.innerHTML=`<div class="panel-heading"><h3>Илгээсэн мэдэгдэл</h3><button class="quiet" type="button" data-messages-refresh>Шинэчлэх</button></div>${r.push_enabled?'':'<p class="muted" style="padding:0 23px">Утасны push сервер дээр идэвхжээгүй тул мэдэгдэл одоогоор зөвхөн жагсаалтад харагдана.</p>'}${r.messages.length?`<div class="table-wrap"><table><thead><tr><th>Огноо</th><th>Төрөл</th><th>Хүлээн авагч</th><th>Гарчиг</th><th>Уншсан</th><th>Утасны push</th></tr></thead><tbody>${r.messages.map(m=>`<tr><td>${esc(new Date(m.created).toLocaleString('mn-MN'))}</td><td>${esc(l.kinds[m.kind]||m.kind)}</td><td>${esc(l.audiences[m.audience]||m.audience)} · ${m.recipients}</td><td title="${esc(m.body)}">${esc(m.title)}</td><td>${m.read}/${m.recipients}</td><td>${esc(messagePushText(m.push))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted" style="padding:0 23px">Одоогоор мэдэгдэл илгээгээгүй байна.</p>'}`;}
 catch(e){if(host.isConnected)host.innerHTML=`<p class="error" style="padding:20px">${esc(e.message)}</p>`;}}
['input','change'].forEach(type=>document.addEventListener(type,e=>{const f=e.target.closest?.('#message-form');if(f)syncMessageForm(f,true);}));
document.addEventListener('click',e=>{if(e.target.closest('[data-messages-refresh]'))loadAdminMessages();});

// Promotional popup (website home page and app launch). Dates are entered in local time and stored in UTC.
const promoLocal=iso=>{if(!iso)return '';const d=new Date(iso),p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes());};
function promoFill(r){const f=$('#promo-form');if(!f)return;const p=r.popup;f.elements.enabled.checked=!!p.enabled;for(const k of ['title','text','button','link','image'])f.elements[k].value=p[k]||'';f.elements.starts.value=promoLocal(p.starts);f.elements.ends.value=promoLocal(p.ends);promoImage(r.preview||'');
 $('#promo-status').textContent=r.live?'Одоо харагдаж байна.':p.enabled?'Идэвхтэй ч хугацаа нь болоогүй эсвэл дууссан.':'Идэвхгүй.';}
function promoImage(src){const box=document.querySelector('.promo-admin-image');if(!box)return;box.hidden=!src;box.querySelector('img').src=src||'';}
async function loadPromoPopup(){if(!$('#promo-form'))return;try{promoFill(await api('admin-promo-popup'));}catch(e){$('#promo-form .error').textContent=e.message;}}
document.addEventListener('change',async e=>{if(e.target.id!=='promo-image-upload'||!e.target.files[0])return;const f=e.target.closest('form'),button=f.querySelector('button.primary');button.disabled=true;f.querySelector('.error').textContent='';
 try{const fd=new FormData();fd.append('image',e.target.files[0]);const response=await fetch('../api/index.php?action=image-upload',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf},body:fd});const result=await response.json();if(!response.ok)throw Error(result.error);f.elements.image.value=result.image;promoImage('../assets/'+result.image+'.jpg');$('#promo-status').textContent='Зураг орууллаа. Хадгалахаа мартуузай.';}
 catch(err){f.querySelector('.error').textContent=err.message;}finally{button.disabled=false;e.target.value='';}});
document.addEventListener('click',e=>{if(!e.target.closest('[data-promo-image-remove]'))return;const f=$('#promo-form');f.elements.image.value='';promoImage('');});
document.addEventListener('submit',async e=>{if(e.target.id!=='promo-form')return;e.preventDefault();const f=e.target,button=f.querySelector('button.primary');button.disabled=true;f.querySelector('.error').textContent='';
 try{const v=k=>f.elements[k].value.trim(),when=k=>f.elements[k].value?new Date(f.elements[k].value).toISOString():'';
  promoFill(await api('admin-promo-popup-save',{enabled:f.elements.enabled.checked,title:v('title'),text:v('text'),button:v('button'),link:v('link'),image:v('image'),starts:when('starts'),ends:when('ends')}));toast('Popup хадгалагдлаа');}
 catch(err){f.querySelector('.error').textContent=err.message;}finally{button.disabled=false;}});
